/** 菜单项配置接口 */
interface MenuItemConfig {
  /** 菜单项标识 */
  action: 'qr-code' | 'ai-chat' | 'remote-control' | 'remote-url'
  /** 是否显示该菜单项 */
  show?: boolean
  /** 菜单项文本 */
  text?: string
  /** 菜单文字颜色 */
  active?: boolean
  /** 识别码 */
  know?: boolean  
  /** 菜单项描述 */
  desc?: string
  /** 菜单项提示 */
  tip?: string
  /** 菜单项图标SVG */
  icon?: string
  /** 是否显示复制图标 */
  showCopyIcon?: boolean
}

/**  配置选项接口 */
interface FloatingBlockOptions {
  /** 弹出 AI 对话框的回调函数 */
  onShowAIChat?: () => void

  /** 遥控端页面地址，默认为： https://ai.opentiny.design/next-remoter */
  qrCodeUrl?: string
  /** 被遥控页面的 sessionId, 必填 */
  sessionId: string
  /** 菜单项配置 */
  menuItems?: MenuItemConfig[]
  /** 遥控端页面地址，默认为： https://agent.opentiny.design/tiny-robot */
  remoteUrl?: string
}

